import * as T from './vendor/three.module.js';

// Every authored lantern gets the same halo and snow reflection, in two draw calls.
// These effects belong to the fixtures; they do not alter character materials or geometry.
export function createFixtureGlow(scene){
 const root=new T.Group();root.name='winter-lantern-glow';root.userData.cameraIgnore=true;
 const positions=[],seeds=[],themes=[],pools=[],point=new T.Vector3();scene.updateMatrixWorld(true);
 scene.traverse(object=>{for(const lamp of object.userData.lampGlow||[]){
  point.set(lamp.x||0,lamp.y,lamp.z||0);object.localToWorld(point);positions.push(point.x,point.y,point.z);seeds.push(positions.length*.618);themes.push(lamp.theme==='fixed'?0:1);
  const floor=new T.Vector3(lamp.x||0,lamp.floor??.12,lamp.z||0);object.localToWorld(floor);pools.push({position:floor,radius:lamp.radius||2.7});
 }});
 const time={value:0},gain={value:1},geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(positions,3));geometry.setAttribute('seed',new T.Float32BufferAttribute(seeds,1));geometry.setAttribute('themeWeight',new T.Float32BufferAttribute(themes,1));geometry.computeBoundingSphere();
 const halos=new T.Points(geometry,new T.ShaderMaterial({transparent:true,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false,uniforms:{time,gain,lightingColor:{value:new T.Color('#ffd5a1')},lightingGain:{value:1}},vertexShader:`uniform float time;attribute float seed;attribute float themeWeight;varying float vTheme;varying float glow;void main(){vTheme=themeWeight;glow=.82+.18*sin(time*.65+seed);vec4 mv=modelViewMatrix*vec4(position,1.);gl_PointSize=clamp(850.*mix(1.,1.22,vTheme)/max(1.,-mv.z),3.,64.);gl_Position=projectionMatrix*mv;}`,fragmentShader:`uniform float gain;uniform vec3 lightingColor;uniform float lightingGain;varying float vTheme;varying float glow;void main(){vec2 p=(gl_PointCoord-.5)*2.;float d=dot(p,p);float aura=exp(-d*6.)*(1.-smoothstep(.65,1.,sqrt(d)));float star=exp(-abs(p.x)*45.-abs(p.y)*7.)+exp(-abs(p.y)*45.-abs(p.x)*7.);gl_FragColor=vec4(mix(vec3(1.,.77,.44),lightingColor,vTheme),(aura*.17+star*.045)*mix(1.,1.25,vTheme)*glow*gain*mix(1.,lightingGain,vTheme));}`}));halos.name='all-lantern-soft-halos';root.add(halos);
 const wash=new T.InstancedMesh(new T.PlaneGeometry(2,2),new T.ShaderMaterial({transparent:true,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false,uniforms:{gain,lightingColor:{value:new T.Color('#ffd5a1')},lightingGain:{value:1}},vertexShader:`attribute float themeWeight;varying float vTheme;varying vec2 vUv;void main(){vTheme=themeWeight;vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*instanceMatrix*vec4(position,1.);}`,fragmentShader:`uniform float gain;uniform vec3 lightingColor;uniform float lightingGain;varying float vTheme;varying vec2 vUv;void main(){vec2 p=(vUv-.5)*2.;float d=length(p);float light=exp(-dot(p,p)*2.8)*(1.-smoothstep(.5,1.,d));gl_FragColor=vec4(mix(vec3(1.,.71,.36),lightingColor,vTheme),light*.18*mix(1.,1.3,vTheme)*gain*mix(1.,lightingGain,vTheme));}`}),pools.length);
 halos.material.userData.lightingTheme=wash.material.userData.lightingTheme='personal';wash.geometry.setAttribute('themeWeight',new T.InstancedBufferAttribute(new Float32Array(themes),1));
 wash.name='all-lantern-snow-reflections';const transform=new T.Object3D();for(let i=0;i<pools.length;i++){transform.position.copy(pools[i].position);transform.rotation.set(-Math.PI/2,0,0);transform.scale.set(pools[i].radius,pools[i].radius,1);transform.updateMatrix();wash.setMatrixAt(i,transform.matrix);}wash.computeBoundingSphere();root.add(wash);scene.add(root);
 return{root,count:pools.length,update(t,still=false){if(!still&&Number.isFinite(t))time.value=t;},setQuality(value){gain.value=value==='low'?.8:1;},dispose(){geometry.dispose();halos.material.dispose();wash.geometry.dispose();wash.material.dispose();root.removeFromParent();}};
}
